// SPDX-License-Identifier: EUPL-1.2
//! the Entities of one type of a view as an RFC 7946 `FeatureCollection`, each `location` its geometry and the other Attributes its properties.
//!
//! `GET /x/views/{view}/geojson/v1/{type}?limit=…&offset=…&q=…` reads the Entities of one type
//! through the view with [`antares_ops::ViewOps::scan`], so the view's narrowing, the Policy
//! and the Tenant decide as for NGSI-LD Query Entities, and `render` writes the page. Read
//! only. A view that is unknown, does not allow Query Entities or does not show the type
//! answers 404 alike. Generated by `dev/new-surface.py` (docs/src/new-surface.md): `render`
//! is what a surface writes; the routing, parameters and refusals are the template's.
//!
//! A view's `representations.geojson` list names outputs (docs API/11 EP-159, T-5216):
//! `geojson/v1/{name}` serves one over its sources' types, each Feature's geometry, JSON-FG
//! `time` and properties from its source's roles, narrowed by its `filter`. Its
//! `representations.csv` list is served the same way at `csv/v1/{name}.csv` (RFC 4180, a `type`
//! column when it maps several types); a name no output lists is a type with every column.
//!
//! ```
//! use antares_ops::Surface;
//! assert_eq!(antares_geojson::GeoJson.name(), "geojson");
//! assert_eq!(antares_geojson::GeoJson.prefix(), "/x/views");
//! ```

#![forbid(unsafe_code)]

use antares_export::csv::{Writer, MEDIA_TYPE};
use antares_export::{Column, Kind, Sink as _};
use antares_ops::outputs::{listed, Output, RoleSource};
use antares_ops::percent::encode;
use antares_ops::{Caller, OperationId, Ops, Page, Pushdown, Scanned, Surface, ViewOps};
use axum::extract::{Path, Query, Request};
use axum::http::header::CONTENT_TYPE;
use axum::http::StatusCode;
use axum::response::{IntoResponse as _, Response};
use axum::routing::any;
use axum::Router;
use serde_json::{json, Map, Value};
use std::collections::BTreeMap;
use std::fmt::Write as _;

/// Where the broker mounts the surface; the view, `geojson/v1` and the type follow.
pub const PREFIX: &str = "/x/views";

/// The most Entities one page holds; `limit` defaults to it (a larger one is `400`, which names 100).
pub const MAX_LIMIT: usize = 100;

/// The most rows of one CSV (an output's `limit` lowers it).
pub const MAX_ROWS: usize = 10_000;

/// The most bytes of one CSV; a larger one is `413`, never a file cut short.
pub const MAX_CSV_BYTES: usize = 4 << 20;

/// The Query Entities parameters passed through as they are (TS 104 175 6.4.3.2).
pub const PASSED: [&str; 3] = ["q", "scopeQ", "lang"];

/// The surface.
#[derive(Debug, Clone, Copy, Default)]
pub struct GeoJson;

/// A boxed answer, the error of a read.
type Answer = Box<Response>;

impl Surface for GeoJson {
    fn name(&self) -> &'static str {
        "geojson"
    }

    fn prefix(&self) -> &'static str {
        PREFIX
    }

    fn version_info(&self) -> Value {
        json!({
            "endpoint": format!("{PREFIX}/{{view}}/geojson/v1/{{type}}"),
            "csv": format!("{PREFIX}/{{view}}/csv/v1/{{name}}.csv"),
        })
    }

    fn router(&self, ops: Ops) -> Router {
        let csv_ops = ops.clone();
        Router::new()
            .route(
                "/{view}/geojson/v1/{type}",
                any(
                    move |caller: Caller,
                          Path((view, ty)): Path<(String, String)>,
                          Query(asked): Query<Vec<(String, String)>>,
                          req: Request| {
                        let ops = ops.clone();
                        async move {
                            let read = async {
                                match entities(&ops, &caller, &view, &ty, asked).await {
                                    Ok((output, entities, next)) => {
                                        render(&output, &entities, next)
                                    }
                                    Err(answer) => *answer,
                                }
                            };
                            antares_ops::read_only(req.method(), read_only, read).await
                        }
                    },
                ),
            )
            .route(
                "/{view}/csv/v1/{file}",
                any(
                    move |caller: Caller,
                          Path((view, file)): Path<(String, String)>,
                          Query(asked): Query<Vec<(String, String)>>,
                          req: Request| {
                        let ops = csv_ops.clone();
                        async move {
                            let read = async {
                                csv(&ops, &caller, &view, &file, asked)
                                    .await
                                    .unwrap_or_else(|answer| *answer)
                            };
                            antares_ops::read_only(req.method(), read_only, read).await
                        }
                    },
                ),
            )
    }
}

/// The refusal of a write.
fn read_only() -> Response {
    problem(StatusCode::METHOD_NOT_ALLOWED, "this surface is read only")
}

/// The members of an Attribute that hold its plain value, one per kind (TS 104 175 4.5).
const VALUE_MEMBERS: [&str; 7] = [
    "value",
    "object",
    "languageMap",
    "json",
    "vocab",
    "valueList",
    "objectList",
];

/// The page as an RFC 7946 `FeatureCollection`: a Feature per Entity, its `id` the Entity's,
/// its geometry and properties as its source maps them (`null` without one, RFC 7946 3.2),
/// `type` among the properties. The foreign member `nextOffset` (RFC 7946 6.1) is the
/// `offset` of the next page, `null` on the last.
fn render(output: &Output, entities: &[Value], next: Option<usize>) -> Response {
    let features: Vec<Value> = entities
        .iter()
        .map(|e| feature(e, source_of(output, e)))
        .collect();
    let body = json!({ "type": "FeatureCollection", "features": features, "nextOffset": next });
    (
        StatusCode::OK,
        [(CONTENT_TYPE, "application/geo+json")],
        body.to_string(),
    )
        .into_response()
}

/// The source of `output` that maps `entity`'s type.
fn source_of<'o>(output: &'o Output, entity: &Value) -> Option<&'o RoleSource> {
    let ty = entity.get("type").and_then(Value::as_str);
    output
        .sources
        .iter()
        .find(|s| Some(s.entity_type.as_str()) == ty)
}

/// One Entity as a Feature: the first `geometry` path with a valid geometry (default
/// `location`), the JSON-FG `time` of its `instant` or `start`/`end` paths, and the
/// `properties` paths (default every other member).
fn feature(entity: &Value, source: Option<&RoleSource>) -> Value {
    let role = |name: &str| source.map(|s| s.role(name)).unwrap_or_default();
    let mut places = role("geometry");
    if places.is_empty() {
        places.push("location");
    }
    // the broker's one geometry rule: the default instance, valid, wound (T-5208)
    let geometry = places
        .iter()
        .map(|p| antares_ops::geometry_of(entity, Some(p)))
        .find(|g| !g.is_null())
        .unwrap_or(Value::Null);
    let shown = role("properties");
    let mut properties = Map::new();
    if shown.is_empty() {
        for (name, member) in entity.as_object().into_iter().flatten() {
            if !["id", "@context"].contains(&name.as_str()) && !places.contains(&name.as_str()) {
                properties.insert(name.clone(), plain(member));
            }
        }
    } else {
        properties.insert(
            "type".into(),
            entity.get("type").cloned().unwrap_or_default(),
        );
        for path in shown {
            properties.insert(path.to_owned(), read(entity, path));
        }
    }
    let mut out = Map::new();
    out.insert("type".into(), "Feature".into());
    out.insert("id".into(), entity.get("id").cloned().unwrap_or_default());
    out.insert("geometry".into(), geometry);
    out.insert("properties".into(), properties.into());
    let first = |name: &str| first_of(entity, &role(name));
    let (instant, start, end) = (first("instant"), first("start"), first("end"));
    let time = if !instant.is_null() {
        json!({ "instant": instant })
    } else if start.is_null() && end.is_null() {
        Value::Null
    } else {
        let open = |v: Value| if v.is_null() { json!("..") } else { v };
        json!({ "interval": [open(start), open(end)] })
    };
    if !time.is_null() {
        out.insert("time".into(), time);
    }
    out.into()
}

/// The value of the first of `paths` that has one, `null` when none has.
fn first_of(entity: &Value, paths: &[&str]) -> Value {
    paths
        .iter()
        .map(|p| read(entity, p))
        .find(|v| !v.is_null())
        .unwrap_or(Value::Null)
}

/// The plain value at `path`: an Attribute (`startDate`) or a dotted path into its value
/// (`address.addressLocality`), `null` where there is none.
fn read(entity: &Value, path: &str) -> Value {
    let mut parts = path.split('.');
    let attribute = parts.next().and_then(|a| entity.get(a)).map(plain);
    parts
        .try_fold(attribute.unwrap_or_default(), |v, key| v.get(key).cloned())
        .unwrap_or_default()
}

/// An Attribute's plain value, each instance in turn when it has several; a member that is no
/// Attribute (`type`) as it is.
fn plain(attribute: &Value) -> Value {
    match attribute {
        Value::Array(instances) => instances.iter().map(plain).collect(),
        Value::Object(members) => VALUE_MEMBERS
            .iter()
            .find_map(|m| members.get(*m))
            .cloned()
            .unwrap_or(Value::Null),
        other => other.clone(),
    }
}

/// A refusal of the surface's own, with a fixed title that never names what a view hides.
fn problem(status: StatusCode, title: &str) -> Response {
    let body = json!({ "title": title, "status": status.as_u16() });
    (
        status,
        [(CONTENT_TYPE, "application/problem+json")],
        body.to_string(),
    )
        .into_response()
}

/// Whether `view` shows the type `ty`.
fn shows(view: &ViewOps, ty: &str) -> bool {
    view.shows_every_name() || view.shown_names().0.iter().any(|t| t == ty)
}

/// The view `id` when it allows Query Entities, and what `name` names on it under `format`:
/// the output the view's list names so, else the type `name` with its defaults. An unknown
/// view, a type it does not show and an output none of whose types it shows are 404 alike; an
/// output that does not hold is 500.
fn target(ops: &Ops, id: &str, format: &str, name: &str) -> Result<(ViewOps, Output), Answer> {
    let missing = || Box::new(problem(StatusCode::NOT_FOUND, "no such collection"));
    let view = ops
        .view(id)
        .filter(|v| v.allows(OperationId::QueryEntities))
        .ok_or_else(missing)?;
    let found = listed(view.representation(format), format)
        .into_iter()
        .find(|(n, _)| n == name);
    let output = match found {
        Some((_, Ok(output))) => output,
        Some((_, Err(_))) => {
            return Err(Box::new(problem(
                StatusCode::INTERNAL_SERVER_ERROR,
                "this output does not hold; its Endpoint must be published again",
            )))
        }
        None => Output {
            name: name.to_owned(),
            version: None,
            title: BTreeMap::new(),
            description: BTreeMap::new(),
            filter: antares_ops::outputs::Filter::default(),
            lang: None,
            limit: None,
            sources: vec![RoleSource {
                entity_type: name.to_owned(),
                mapping: BTreeMap::new(),
            }],
        },
    };
    if !output.sources.iter().any(|s| shows(&view, &s.entity_type)) {
        return Err(missing());
    }
    Ok((view, output))
}

/// The Query Entities of `output` on `view`: the types of its sources the view shows, and the
/// caller's `passed` parameters under its filter and its `lang`.
fn pushdown(
    view: &ViewOps,
    output: &Output,
    mut passed: BTreeMap<String, String>,
) -> Result<Pushdown, Answer> {
    output
        .filter
        .narrow(&mut passed)
        .map_err(|why| Box::new(problem(StatusCode::BAD_REQUEST, why)))?;
    if let Some(lang) = &output.lang {
        passed.entry("lang".into()).or_insert_with(|| lang.clone());
    }
    let types: Vec<String> = output
        .sources
        .iter()
        .filter(|s| shows(view, &s.entity_type))
        .map(|s| encode(&s.entity_type))
        .collect();
    let mut query = format!("type={}", types.join(","));
    for (k, v) in passed {
        // writing to a String cannot fail
        let _ = write!(query, "&{k}={}", encode(&v));
    }
    Ok(Pushdown {
        query,
        ..Pushdown::default()
    })
}

/// One page of `pushdown` on `view` and the next page's offset.
async fn scan(
    view: &ViewOps,
    caller: &Caller,
    pushdown: &Pushdown,
    page: Page,
) -> Result<(Vec<Value>, Option<usize>), Answer> {
    match view.scan(caller, pushdown, None, page).await {
        Ok(Scanned::Page { entities, next, .. }) => Ok((entities, next)),
        // A Tenant that holds nothing yet answers 404 (5.5.10): an empty page.
        Ok(Scanned::Answer(a)) if a.status() == StatusCode::NOT_FOUND => Ok((Vec::new(), None)),
        Ok(Scanned::Answer(a)) => Err(Box::new(a)),
        Err(refusal) => Err(Box::new(refusal.ngsi_ld())),
    }
}

/// The Entities `name` names that the caller reads through view `id`, and the next page's
/// offset.
async fn entities(
    ops: &Ops,
    caller: &Caller,
    id: &str,
    name: &str,
    asked: Vec<(String, String)>,
) -> Result<(Output, Vec<Value>, Option<usize>), Answer> {
    let (view, output) = target(ops, id, "geojson", name)?;
    // the output's limit is the default page size; offset pages through the rest, so a
    // caller's own limit (1 to MAX_LIMIT) widens nothing the view or the Policy bounds
    let size = output
        .limit
        .map_or(MAX_LIMIT, |n| usize::try_from(n).unwrap_or(MAX_LIMIT))
        .min(MAX_LIMIT);
    let (page, passed) = parameters(asked, size)
        .map_err(|title| Box::new(problem(StatusCode::BAD_REQUEST, title)))?;
    let pushdown = pushdown(&view, &output, passed)?;
    let (entities, next) = scan(&view, caller, &pushdown, page).await?;
    Ok((output, entities, next))
}

/// The CSV `file` (`{name}.csv`) names on view `id`: a header row, then a row per Entity up
/// to the output's `limit` (at most [`MAX_ROWS`]): `id`, `type` when the output maps several
/// types, then each source's `columns` (default every Attribute its Entities hold) in order.
async fn csv(
    ops: &Ops,
    caller: &Caller,
    id: &str,
    file: &str,
    asked: Vec<(String, String)>,
) -> Result<Response, Answer> {
    let name = file
        .strip_suffix(".csv")
        .ok_or_else(|| Box::new(problem(StatusCode::NOT_FOUND, "no such collection")))?;
    let (view, output) = target(ops, id, "csv", name)?;
    if asked.iter().any(|(k, _)| !PASSED.contains(&k.as_str())) {
        return Err(Box::new(problem(
            StatusCode::BAD_REQUEST,
            "the parameters are q, scopeQ and lang",
        )));
    }
    let (_, passed) = parameters(asked, MAX_LIMIT)
        .map_err(|title| Box::new(problem(StatusCode::BAD_REQUEST, title)))?;
    let pushdown = pushdown(&view, &output, passed)?;
    let rows = output
        .limit
        .map_or(MAX_ROWS, |n| usize::try_from(n).unwrap_or(MAX_ROWS))
        .min(MAX_ROWS);
    let mut all = Vec::new();
    let mut start = Some(0);
    while let Some(at) = start.filter(|_| all.len() < rows) {
        let size = rows.saturating_sub(all.len()).min(MAX_LIMIT);
        let (entities, next) = scan(
            &view,
            caller,
            &pushdown,
            Page {
                start: at,
                size,
                whole: false,
            },
        )
        .await?;
        all.extend(entities);
        start = next;
    }
    let mut columns: Vec<String> = Vec::new();
    if output.sources.len() > 1 {
        columns.push("type".into());
    }
    for source in &output.sources {
        let mapped = source.role("columns");
        let named: Vec<String> = if mapped.is_empty() {
            let mut held: Vec<String> = all
                .iter()
                .filter(|e| source_of(&output, e) == Some(source))
                .flat_map(|e| e.as_object().into_iter().flatten().map(|(k, _)| k.clone()))
                .filter(|k| !["id", "type", "@context"].contains(&k.as_str()))
                .collect();
            held.sort();
            held
        } else {
            mapped.into_iter().map(str::to_owned).collect()
        };
        for column in named {
            if !columns.contains(&column) {
                columns.push(column);
            }
        }
    }
    let features: Vec<Value> = all
        .iter()
        .map(|e| {
            let cells: Map<String, Value> =
                columns.iter().map(|c| (c.clone(), read(e, c))).collect();
            json!({ "id": e.get("id"), "properties": cells })
        })
        .collect();
    let columns = columns
        .into_iter()
        .map(|name| Column {
            name,
            kind: Kind::Json,
        })
        .collect();
    let bytes = Writer::new(columns, false, MAX_CSV_BYTES)
        .and_then(|mut w| {
            w.page(&features)?;
            Box::new(w).finish(&[])
        })
        .map_err(|_| {
            Box::new(problem(
                StatusCode::PAYLOAD_TOO_LARGE,
                "the file is larger than the answer may be; narrow it with q",
            ))
        })?;
    Ok((StatusCode::OK, [(CONTENT_TYPE, MEDIA_TYPE)], bytes).into_response())
}

/// The page a query string asks for (`limit` defaults to `size`) and what it passes to Query
/// Entities, or why it is `400`: any other parameter, a repeated one, or a `limit` outside 1
/// to [`MAX_LIMIT`].
fn parameters(
    asked: Vec<(String, String)>,
    size: usize,
) -> Result<(Page, BTreeMap<String, String>), &'static str> {
    let mut seen = BTreeMap::new();
    for (key, value) in asked {
        if seen.insert(key, value).is_some() {
            return Err("a parameter is given more than once");
        }
    }
    let known = |k: &str| k == "limit" || k == "offset" || PASSED.contains(&k);
    if !seen.keys().all(|k| known(k)) {
        return Err("the parameters are limit, offset, q, scopeQ and lang");
    }
    let number = |name: &str, default: usize| {
        seen.get(name).map_or(Ok(default), |v| {
            v.parse::<usize>()
                .map_err(|_| "limit and offset take a whole number")
        })
    };
    let size = number("limit", size)?;
    if !(1..=MAX_LIMIT).contains(&size) {
        return Err("limit is 1 to 100");
    }
    let start = number("offset", 0)?;
    let passed = seen
        .into_iter()
        .filter(|(k, _)| PASSED.contains(&k.as_str()))
        .collect();
    let page = Page {
        start,
        size,
        whole: false,
    };
    Ok((page, passed))
}
